// Types and loader for public/data/results.json (generated by scripts/build_web_data.py; never edited by hand).

export interface TCI { mean: number | null; lo: number | null; hi: number | null; n: number; p?: number | null }

export interface Cell {
  label: "B" | "C" | "C_l0" | "C_shuf" | "B_ckpt" | "C_ckpt";
  adapter: "lora" | "dora" | "qlora";
  language: "arabic" | "malay";
  n_seeds: number;
  mean_f_faith: number; mean_f_faith_sd: number | null;
  mean_em: number; mean_em_sd: number | null;
  mean_f1: number; mean_f1_sd: number | null;
  option_acc?: number | null;
  trainmode_eval_f_faith?: number | null;
}

export interface SeedRow { adapter: string; language: string; seed: number; [k: string]: number | string | null }

export interface Contrast {
  contrast: string; scope: string; metric: string; n_seeds: number; mean: number | null;
  ci95_lo: number | null; ci95_hi: number | null; p: number | null; ci90_lo: number | null; ci90_hi: number | null;
  equivalent_within_margin: boolean | number | null; cells_positive: string | null; p_holm: number | null;
}

export interface BootstrapCI { point: number; ci95: [number, number] }
export interface LenBin { n_pairs: number; mean_diff?: number; ci95?: [number, number]; mean_B?: number; mean_C?: number; note?: string }

export interface WorkedExample {
  language: string; src_id: string; passage: string; question: string; gold: string;
  B: ExampleAnswer; C: ExampleAnswer;
}
export interface ExampleAnswer { answer: string; f_faith: number; f_indep: number; sup1: number; sup2: number; cor1: number; cor2: number }

export interface FirstRow {
  backbone: "mt5" | "qwen3" | "t5gemma2"; adapter: string; language: string; seeds: number[];
  B: number; C: number; delta: number; delta_per_seed: number[];
  em_B: number; em_C: number; f1_B: number; f1_C: number;
}

export interface RankRow { model: string; name: string; mean: number; sd: number; n: number; per_unit: number[] }
export interface CmpResult { ranking: RankRow[]; winner: string; runner_up: string; margin: number; lo: number | null; hi: number | null; p: number | null; clear: boolean }
export interface OutputAnswer { generated: string; em: number; f1: number }
export interface OutputItem {
  id: string; language: string; question: string; context: string; gold: string;
  answers: Record<string, Record<string, Record<string, OutputAnswer>>>;
}
export interface Compare {
  models: Record<string, string>; adapters: string[]; seeds: number[]; protocol_note: string;
  results: Record<string, CmpResult>; outputs: OutputItem[];
}

export interface ResultsFile {
  compare: Compare;
  meta: { base_model: string; reward_model: string; independent_scorer: string; margin: number };
  corrected: {
    n_runs: number; seeds: number[];
    headline: Record<string, TCI>; by_adapter: Record<string, TCI>;
    cells: Cell[]; per_seed: SeedRow[]; contrasts: Contrast[];
    joint_bootstrap: Record<string, Record<string, BootstrapCI | Record<string, number>>>;
    length_matched: {
      bin_means: Record<string, { B: { n: number; mean: number | null }; C: { n: number; mean: number | null } }>;
      pairs_total: number; pairs_same_bin: number; matched_by_bin: Record<string, LenBin>;
      matched_overall: { mean_diff: number; ci95: [number, number]; n_pairs: number; share_of_all_pairs: number };
      fe_regression_C_coef: { estimate: number; ci95: [number, number] };
      share_long: { B: number; C: number };
    };
    answer_length: Record<string, { n: number; mean_words: number; in_context_rate: number; share_gt_3x_gold: number }>;
    diagnostics: {
      sanitize_total: Record<string, number>; runs_with_nonfinite_logits: number; n_failed_runs: number; n_runs: number;
      legacy_eval_state_minus_headline_by_label: Record<string, number>;
      frac_eval_prompt_truncated: { mean: number; max: number };
    };
    examples: WorkedExample[];
  };
  independent: Record<string, unknown> & { spearman_reward_vs_indep?: number };
  human: {
    sensitivity: Record<string, { delta?: number; ci95?: number[]; n?: number; C_lower_equal_higher?: number[] } | number>;
    annotator_vs_option: Record<string, unknown>;
    summary: { kappa_supported_quadratic?: number; kappa_correct?: number; [k: string]: unknown };
  };
  first_study: {
    rows: FirstRow[];
    summary: Record<string, { pooled: TCI; n_runs: number }>;
    reanalysis: Record<string, Record<string, { delta: number; lo: number; hi: number; p: number; p_welch: number; per_seed: number[]; seeds_same_sign: number }> & Record<string, unknown>>;
  };
}

let cache: Promise<ResultsFile> | null = null;
export function loadResults(): Promise<ResultsFile> {
  if (!cache) {
    cache = fetch(`${import.meta.env.BASE_URL}data/results.json`).then((r) => {
      if (!r.ok) throw new Error(`results.json: HTTP ${r.status}`);
      return r.json() as Promise<ResultsFile>;
    });
  }
  return cache;
}
